/* ===== 24 ui claims: register, claim detail (evidence chain), evidence, conflicts, authorities, citation audit, timeline ===== */
UI.cs = { q: '', f: 'all', sort: 'id', dir: 1 }; UI.ev = { q: '', f: 'All' }; UI.au = { q: '' }; UI.tl = { doc: '', spk: '', overlay: true };
const REL_STYLE = { SUPPORTS: ['var(--ok)', '', 'Supports'], CONFLICTS: ['var(--bad)', '7 4', 'Conflicts'], CONTEXTUALIZES: ['var(--accent)', '2 4', 'Contextualizes'], UNCERTAIN: ['var(--warn)', '9 3 2 3', 'Uncertain'], MENTIONS: ['var(--idle)', '1 3', 'Mentions'] };
const relBadge = r => { const k = { SUPPORTS: 'ok', CONFLICTS: 'bad', CONTEXTUALIZES: 'info', UNCERTAIN: 'warn', MENTIONS: '' }[r] || ''; const ic = { SUPPORTS: 'check', CONFLICTS: 'warn', CONTEXTUALIZES: 'link', UNCERTAIN: 'help', MENTIONS: 'quote' }[r] || 'circle'; return `<span class="badge ${k}">${icon(ic, 12)}${esc((REL_STYLE[r] || [0, 0, r])[2])}</span>`; };
const scrollToId = id => { const el = document.getElementById(id); el && el.scrollIntoView({ block: 'start', behavior: prefs().reduceMotion ? 'auto' : 'smooth' }); };
ACT.scroll = el => scrollToId(el.dataset.to);
const chainCell = (ic, k, v, s, o = {}) => { const tag = o.to ? `<a href="#" data-act="scroll" data-to="${o.to}"` : o.href ? `<a href="${o.href}"` : '<div'; return `${tag} class="${o.cls || ''}"><div class="k">${icon(ic, 13)}${k}</div><div class="v">${v}</div><div class="s">${s}</div></${o.to || o.href ? 'a' : 'div'}>`; };

/* ---------- review form (shared by claim detail, review workspace, citation audit) ---------- */
const REV_OPTS = [['accept', 'Accept finding', 'Confirm the finding is correct'], ['reject', 'Reject finding', 'The finding should not stand'], ['modify', 'Modify wording', 'Record your own wording. The original is kept'], ['verify', 'Needs further verification', 'Keep it open until it is verified'], ['comment', 'Comment only', 'Add a note without changing the status']];
function reviewForm(C, f, o = {}) {
  const st = findingStatus(C, f); const hist = ReviewSvc.forFinding(C, f.id).slice().reverse(); const X = derive(C); const c0 = f.kind === 'CLAIM' ? X.claim(f.claimIds[0]) : null;
  const lastMod = hist.find(h => h.action === 'modify'); const initial = lastMod ? lastMod.modifiedText : (c0 ? c0.text : f.why || f.title);
  const ro = C.status === 'ARCHIVED';
  return `<form data-form="review" data-case="${C.id}" data-finding="${f.id}" novalidate class="col" style="gap:12px"><div class="row between"><b>Your decision</b>${badge(st === 'PENDING' ? 'PENDING' : st)}</div><div id="revErr-${f.id}" role="alert"></div>
  <div class="col" style="gap:7px" role="radiogroup" aria-label="Review decision">${REV_OPTS.map(([v, l, h]) => `<label class="radio"><input type="radio" name="action" value="${v}" data-change="revact" ${ro ? 'disabled' : ''}><span><b>${l}</b><small>${h}</small></span></label>`).join('')}</div>
  <div class="field hide" data-modwrap><label for="mt-${f.id}">Reviewer wording</label><textarea id="mt-${f.id}" name="modifiedText" maxlength="1000">${esc(initial)}</textarea></div>
  <div class="field"><label for="rc-${f.id}">Reviewer comment</label><textarea id="rc-${f.id}" name="comment" maxlength="2000" placeholder="What did you check, or what still needs checking?" ${ro ? 'disabled' : ''}></textarea></div>
  <div class="row between"><button class="btn primary" type="submit" ${ro ? 'disabled' : ''}>Save review</button><span class="faint" style="font-size:12px">${icon('lock', 12)} Original AI finding is never overwritten</span></div></form>
  ${hist.length ? `<div style="margin-top:18px"><div class="lbl" style="margin-bottom:8px">Review history</div><ul class="tl">${hist.map(h => `<li class="rev"><div class="t">${esc(fmtDT(h.createdAt))} · ${esc(h.reviewerName)}</div><div class="d"><b>${esc(ReviewSvc.ACTIONS[h.action][1])}</b>${h.newStatus !== h.previousStatus ? ` <span class="faint">(${esc(REVIEW_BADGE[h.previousStatus === 'PENDING' ? 'PENDING' : h.previousStatus][2])} → ${esc(REVIEW_BADGE[h.newStatus][2])})</span>` : ''}${h.comment ? `<div class="muted" style="margin-top:2px">${esc(h.comment)}</div>` : ''}${h.modifiedText ? `<div class="serif" style="margin-top:4px;padding:8px 10px;border-left:3px solid var(--ok);background:var(--sunken)">${esc(h.modifiedText)}</div>` : ''}</div></li>`).join('')}</ul></div>` : ''}`;
}
INPUT.revact = t => { const f = t.closest('form'); const w = $('[data-modwrap]', f); w && w.classList.toggle('hide', t.value !== 'modify'); };
FORM.review = async f => {
  const d = {}; new FormData(f).forEach((v, k) => d[k] = v); const err = $('#revErr-' + f.dataset.finding);
  try { await Data.saveReview(f.dataset.case, f.dataset.finding, { action: d.action, comment: d.comment, modifiedText: d.modifiedText }); closeOverlay(); toast(`Finding ${f.dataset.finding} updated.`); render(); }
  catch (e) { if (err) err.innerHTML = `<div class="note warn">${icon('alert', 14)}<span>${esc(e.message || 'The review could not be saved.')}</span></div>`; }
};
function openFinding(C, f) { const k = C.id + f.id; if (!UI.opened.has(k)) { UI.opened.add(k); Data.openFinding(C.id, f.id); } }

/* ---------- claim register ---------- */
const CLAIM_FILTERS = [['all', 'All'], ['supported', 'Supported'], ['conflict', 'Conflicting'], ['unverified', 'Unverified'], ['reviewed', 'Reviewed'], ['needs', 'Needs verification']];
function claimPass(f, i) { return f === 'all' ? true : f === 'supported' ? (i.strong.some(r => r.rel.relationship === 'SUPPORTS') && !i.inConflict) : f === 'conflict' ? i.inConflict : f === 'unverified' ? i.unresolved : f === 'reviewed' ? i.reviewed : (i.status === 'NEEDS_REVIEW' || i.status === 'NEEDS_VERIFICATION'); }
function ClaimsView(C) {
  const X = derive(C); const infos = C.claims.map(c => X.info(c)); const mkHead = exp => `<div class="pagehead"><div><p class="lbl" style="margin-bottom:6px">Claim register</p><h1>${plural(C.claims.length, 'extracted claim')}</h1><p class="sub">${infos.filter(i => i.reviewed).length} reviewed · ${infos.filter(i => i.status === 'NEEDS_REVIEW' || i.status === 'NEEDS_VERIFICATION').length} need review · ${infos.filter(i => i.unresolved).length} unresolved</p></div>${exp ? `<div class="row">${btn('Export claims (CSV)', 'data-act="export-claims" data-case="' + C.id + '"', { icon: 'download' })}</div>` : ''}</div>`; const head = mkHead(C.claims.length > 0);
  if (!C.claims.length) return { title: 'Claims', workspace: 'Claim register', crumbs: crumbsFor(C, ['Claims']), html: `<div class="page">${head}${empty({ icon: 'quote', title: 'No claims extracted', text: 'Claims will appear here after the case material has been analysed.', action: `<div style="margin-top:10px">${C.documents.length ? btn('Run analysis', `data-act="run-analysis" data-case="${C.id}"`, { cls: 'primary', icon: 'play' }) : linkBtn('Add material', caseHref(C, 'setup/materials'), { cls: 'primary' })}</div>` })}</div>` };
  return { title: 'Claims', workspace: 'Claim register', crumbs: crumbsFor(C, ['Claims']), mount: paintClaims, html: `<div class="page wide">${head}<div class="row wrap between" style="margin-bottom:14px"><div class="chips" id="claimchips"></div><div class="searchin" style="width:280px;max-width:100%">${icon('search', 15)}<input type="text" data-in="claimq" placeholder="Search claims…" aria-label="Search claims" value="${esc(UI.cs.q)}"></div></div><div id="claimlist"></div></div>` };
}
function paintClaims() {
  const C = currentCaseSafe(); if (!C || !$('#claimlist')) return; const X = derive(C); const q = UI.cs.q.trim().toLowerCase();
  const all = C.claims.map(c => ({ c, i: X.info(c) })); $('#claimchips').innerHTML = CLAIM_FILTERS.map(([k, l]) => `<button class="chip" aria-pressed="${UI.cs.f === k}" data-act="claim-filter" data-k="${k}">${l}<span class="n">${all.filter(x => claimPass(k, x.i)).length}</span></button>`).join('');
  let rows = all.filter(x => claimPass(UI.cs.f, x.i)).filter(x => !q || (x.c.text + ' ' + x.c.id + ' ' + (x.c.speaker || '')).toLowerCase().includes(q));
  const key = { id: x => x.c.id, support: x => x.c.supportStrength, conflict: x => x.c.conflictStrength, uncertainty: x => x.c.uncertainty }[UI.cs.sort] || (x => x.c.id); rows.sort((a, b) => (key(a) > key(b) ? 1 : key(a) < key(b) ? -1 : 0) * UI.cs.dir);
  const th = (k, l) => `<th aria-sort="${UI.cs.sort === k ? (UI.cs.dir > 0 ? 'ascending' : 'descending') : 'none'}"><button data-act="claim-sort" data-k="${k}">${l}${UI.cs.sort === k ? icon(UI.cs.dir > 0 ? 'up' : 'down', 12) : ''}</button></th>`;
  $('#claimlist').innerHTML = rows.length ? `<div class="tblwrap"><table><thead><tr>${th('id', 'ID')}<th>Claim</th><th>Source</th><th>Speaker</th><th>Evidence</th>${th('support', 'Support')}${th('conflict', 'Conflict')}${th('uncertainty', 'Uncertainty')}<th>Review status</th></tr></thead><tbody>${rows.map(({ c, i }) => `<tr data-href="${caseHref(C, 'claims/' + c.id)}"><td class="idcell"><a href="${caseHref(C, 'claims/' + c.id)}">${c.id}</a></td><td class="qtext serif" style="font-size:14.5px;min-width:280px">${esc(trunc(c.text, 170))}<div class="row" style="gap:6px;margin-top:4px"><span class="tag">${esc(typeLabel(c.type))}</span>${c.provider === 'gemini' ? `<span class="tag" title="Extracted by ${esc(c.model)}">Gemini</span>` : ''}</div></td><td style="font-size:12.5px;min-width:170px"><a href="${X.href(c)}">${esc(X.src(c))}</a></td><td>${esc(c.speaker || '—')}</td><td class="mono">${i.evCount || '—'}</td><td>${sig(c.supportStrength, 'ok')}</td><td>${sig(c.conflictStrength, 'bad')}</td><td>${sig(c.uncertainty, 'warn')}</td><td>${badge(i.status)}${i.inConflict ? `<div style="margin-top:4px">${badge('CONFLICT')}</div>` : ''}</td></tr>`).join('')}</tbody></table></div>` : empty({ icon: 'search', title: 'No claims match', text: 'Try another filter or search term.' });
}
ACT['claim-filter'] = el => { UI.cs.f = el.dataset.k; paintClaims(); };
ACT['claim-sort'] = el => { const k = el.dataset.k; if (UI.cs.sort === k) UI.cs.dir *= -1; else { UI.cs.sort = k; UI.cs.dir = k === 'id' ? 1 : -1; } paintClaims(); };
INPUT.claimq = t => { UI.cs.q = t.value; paintClaims(); };
ACT['export-claims'] = el => { const C = CaseSvc.get(UI.user.id, el.dataset.case); const R = buildReport(C, UI.user); const q = v => '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"'; const rows = [['id', 'claim', 'type', 'speaker', 'document', 'page', 'paragraph', 'timestamp', 'status', 'support_signal', 'conflict_signal', 'uncertainty_signal', 'extraction_confidence'].join(',')].concat(R.claims.map(c => [c.id, c.text, c.type, c.speaker, c.source.document, c.source.page, c.source.paragraph, c.source.timestamp, c.status, c.supportSignal, c.conflictSignal, c.uncertaintySignal, c.extractionConfidence].map(q).join(','))); saveFile(`${C.id}-claims.csv`, '\ufeff' + rows.join('\r\n'), 'text/csv'); };

/* ---------- claim detail ---------- */
function relMini(C, X, c, rels) {
  const shown = rels.slice(0, 6), extra = rels.length - shown.length; const W = 720, gap = W / (shown.length || 1); const nodes = shown.map((r, i) => ({ r, x: gap * i + gap / 2 }));
  return `<svg class="mini" viewBox="0 0 ${W} 200" role="img" aria-label="Relationships of ${c.id}"><g><rect x="${W / 2 - 70}" y="6" width="140" height="40" rx="4" fill="var(--accent)"/><text x="${W / 2}" y="22" text-anchor="middle" class="mono" font-size="12" font-weight="600" style="fill:var(--accent-fg)">CLAIM</text><text x="${W / 2}" y="38" text-anchor="middle" class="mono" font-size="12" style="fill:var(--accent-fg)">${c.id}</text></g>
  ${nodes.map(({ r, x }) => { const [col, dash, lab] = REL_STYLE[r.rel.relationship] || REL_STYLE.MENTIONS; const d = X.doc(r.ev.sourceDocId); return `<g><path d="M${W / 2} 46 C ${W / 2} 96, ${x} 92, ${x} 132" fill="none" stroke="${col}" stroke-width="1.8" ${dash ? `stroke-dasharray="${dash}"` : ''}/><text x="${x}" y="122" text-anchor="middle" font-size="9.5" class="mono" style="fill:${col};font-weight:600;paint-order:stroke;stroke:var(--bg);stroke-width:3px">${lab.toUpperCase()}</text><g style="cursor:pointer" role="button" tabindex="0" data-act="ev-open" data-id="${r.ev.id}"><rect x="${x - 62}" y="132" width="124" height="58" rx="4" fill="var(--surface)" stroke="${col}" stroke-width="1.4"/><text x="${x}" y="150" text-anchor="middle" class="mono" font-size="11.5" font-weight="600" style="fill:var(--gold-text)">${r.ev.id}</text><text x="${x}" y="165" text-anchor="middle" font-size="10.5" style="fill:var(--text)">${esc(trunc(EVIDENCE_LABEL[r.ev.type] || r.ev.type, 20))}</text><text x="${x}" y="180" text-anchor="middle" font-size="10" style="fill:var(--text-3)">${esc(trunc(docName(d), 20))}</text></g></g>`; }).join('')}
  ${extra > 0 ? `<text x="${W - 4}" y="196" text-anchor="end" font-size="11" style="fill:var(--text-3)">+${extra} more below</text>` : ''}</svg>`;
}
function evRow(C, X, r) {
  const e = r.ev, d = X.doc(e.sourceDocId); const cls = { SUPPORTS: 's', CONFLICTS: 'c' }[r.rel.relationship] || 'x';
  return `<div class="evrow ${cls}"><span class="idcell" style="padding-top:2px"><button class="tag" data-act="ev-open" data-id="${e.id}">${e.id}</button></span><div style="min-width:0"><div class="row wrap" style="gap:6px"><span class="tag">${esc(EVIDENCE_LABEL[e.type] || e.type)}</span>${relBadge(r.rel.relationship)}</div><div style="margin-top:5px">${esc(e.description)}</div><div class="muted" style="font-size:12.5px;margin-top:3px">${esc(r.rel.reason)}</div><div class="faint" style="font-size:12px;margin-top:3px">${esc(r.rel.sourceLocation || (d ? docName(d) + ', page ' + e.page : ''))}${r.rel.assessmentSignal != null ? ` · assessment signal <span class="mono">${r.rel.assessmentSignal}</span>` : ''}</div></div><div>${d ? `<a class="btn sm" href="${docHref(C, d)}${d.kind === 'transcript' ? '' : '?page=' + e.page}">Open source</a>` : ''}</div></div>`;
}
function ClaimDetailView(C, id) {
  const X = derive(C); const c = X.claim(id); if (!c) return { title: 'Claim not found', crumbs: crumbsFor(C, ['Claims', caseHref(C, 'claims')], ['Not found']), html: `<div class="page narrow">${empty({ icon: 'quote', title: 'Claim not found', text: 'This claim is not part of the case. It may have been removed by a re-run of the analysis.', action: `<div style="margin-top:10px">${linkBtn('Back to claims', caseHref(C, 'claims'), { cls: 'primary' })}</div>` })}</div>` };
  const inf = X.info(c), f = claimFinding(C, c.id), d = X.doc(c.sourceDocId), p = X.para(c); const auditEv = C.audit.filter(e => e.object === c.id || (f && e.object === f.id) || (e.description || '').includes(c.id)); const cites = X.cites.get(c.id) || [], auths = X.auth.get(c.id) || []; const grouped = ['SUPPORTS', 'CONFLICTS', 'CONTEXTUALIZES', 'UNCERTAIN', 'MENTIONS'].flatMap(k => inf.rels.filter(r => r.rel.relationship === k)); const sf = c.signalFactors || {};
  const idx = C.claims.findIndex(x => x.id === c.id); const prev = C.claims[idx - 1], next = C.claims[idx + 1];
  const chain = `<div class="chain">${chainCell('file', 'Source', esc(d ? trunc(docName(d), 22) : '—'), c.sourceType === 'TRANSCRIPT' ? esc(c.timestamp || '') : `p.${c.page} · ¶${c.para}`, { href: X.href(c) })}${chainCell('quote', 'Claim', c.id, esc(typeLabel(c.type)), { to: 'st-claim' })}${chainCell('layers', 'Evidence', inf.evCount ? plural(inf.evCount, 'item') : 'None linked', inf.strong.length ? plural(inf.strong.length, 'link') + ' with reasons' : 'no corroboration', { to: 'st-evidence', cls: inf.evCount ? '' : 'warn' })}${chainCell('warn', 'Conflict', inf.inConflict ? plural(inf.conflicts.length, 'potential conflict') : 'None flagged', inf.inConflict ? esc(inf.conflicts[0].id) : 'in current analysis', { to: 'st-conflict', cls: inf.inConflict ? 'bad' : 'ok' })}${chainCell('eye', 'Review', esc(REVIEW_BADGE[inf.status][2]), f ? f.id : '—', { to: 'st-review', cls: inf.reviewed ? 'ok' : 'warn' })}${chainCell('history', 'Audit', plural(auditEv.length, 'event'), auditEv.length ? fmtClock(auditEv[auditEv.length - 1].ts) : '—', { to: 'st-audit' })}</div>`;
  const passage = p ? `<div class="passage">${esc(p.text.slice(0, c.start))}<mark>${esc(p.text.slice(c.start, c.end))}</mark>${esc(p.text.slice(c.end))}</div>` : '<div class="note warn">The source text is no longer available.</div>';
  const factors = k => (sf[k] || []).map(x => `<li><span>${esc(x.name)}</span><span class="mono">${x.points > 0 ? '+' : ''}${x.points}</span></li>`).join('');
  const detail = `<div class="split"><div class="rail">
   <section class="station" id="st-claim"><h2>Source</h2><div class="q">Where in the case material does this claim come from?</div>${passage}<div class="row wrap" style="margin-top:10px;gap:10px"><span class="mono muted" style="font-size:12.5px">${esc(X.src(c))}</span>${c.speaker ? `<span class="muted" style="font-size:12.5px">Speaker: ${esc(c.speaker)}</span>` : ''}${linkBtn('Open in document viewer', X.href(c), { cls: 'sm', icon: 'ext' })}</div></section>
   <section class="station ${inf.inConflict ? 'warn' : ''}" id="st-evidence"><h2>Evidence</h2><div class="q">What else in the case is linked to this claim, and why?</div>${inf.rels.length ? `${relMini(C, X, c, grouped)}<div style="margin-top:14px">${grouped.map(r => evRow(C, X, r)).join('')}</div><div class="row wrap" style="margin-top:12px;gap:14px;font-size:12px" class="muted">${Object.entries(REL_STYLE).map(([k, v]) => `<span class="row" style="gap:6px"><svg width="26" height="6"><line x1="0" y1="3" x2="26" y2="3" stroke="${v[0]}" stroke-width="2" ${v[1] ? `stroke-dasharray="${v[1]}"` : ''}/></svg>${v[2]}</span>`).join('')}</div>` : `<div class="note">${icon('info', 14)}<span>No other source in the case material was linked to this claim. This can reflect missing material rather than a problem with the claim.</span></div>`}</section>
   <section class="station ${inf.inConflict ? 'bad' : 'ok'}" id="st-conflict"><h2>Potential conflicts</h2><div class="q">Do other sources describe this differently?</div>${inf.conflicts.length ? inf.conflicts.map(k => { const fk = C.findings.find(x => x.conflictId === k.id); return `<div class="evrow c" style="grid-template-columns:1fr auto"><div><div class="row wrap" style="gap:6px"><span class="tag">${k.id}</span>${badge('CONFLICT', typeLabel(k.type) + ' inconsistency')}${fk ? badge(findingStatus(C, fk)) : ''}</div><p style="margin-top:6px">${esc(k.description)}</p></div><div class="col" style="gap:6px">${btn('Compare sources', `data-act="compare" data-id="${k.id}"`, { cls: 'sm primary', icon: 'compare' })}${fk ? linkBtn('Review finding', caseHref(C, 'review/' + fk.id), { cls: 'sm' }) : ''}</div></div>`; }).join('') : `<div class="note">${icon('check', 14)}<span>No potential conflicts were identified for this claim in the current analysis.</span></div>`}</section>
   <section class="station" id="st-authority"><h2>Authority</h2><div class="q">Which authorities in your library contain a related passage?</div>${AUTHORITIES.length === 0 ? `<div class="note warn">${icon('book', 14)}<span>Your authority library is empty, so nothing could be retrieved. ${`<a href="#/authorities">Add authorities</a>`} and re-run the analysis.</span></div>` : auths.length ? auths.map(l => { const a = AUTH_BY_ID[l.authorityId]; return a ? `<div class="evrow x" style="grid-template-columns:1fr"><div><div class="row wrap" style="gap:8px"><b class="serif" style="font-size:15px">${esc(a.title)}</b><span class="tag">${esc(a.citation)}</span>${HUMAN_NOTE}</div><div class="faint" style="font-size:12.5px;margin:2px 0 6px">${esc([a.court, a.year, a.kind].filter(Boolean).join(' · '))} · passage ${l.passageIndex}</div><div class="passage" style="font-size:14.5px">${esc(l.passage)}</div><div class="faint" style="font-size:12px;margin-top:6px">Retrieval signal <span class="mono">${l.score}</span> — a ranking signal, not legal correctness. This passage appears related to the claim and should be verified by the reviewer.</div></div></div>` : ''; }).join('') : `<div class="note">${icon('info', 14)}<span>No passage in your library was ranked as related to this claim.</span></div>`}
     ${cites.length ? `<div class="lbl" style="margin:14px 0 8px">Citations attached to this claim</div>${cites.map(x => `<a class="evrow x" href="${caseHref(C, 'citations?cit=' + x.id)}" style="grid-template-columns:1fr auto;color:inherit"><div><span class="mono" style="font-size:12.5px">${esc(x.citationText)}</span><div class="muted" style="font-size:12.5px;margin-top:3px">${esc(x.note)}</div></div>${badge(x.result === 'POTENTIALLY_RELEVANT' ? 'ACCEPTED' : 'NEEDS_REVIEW', CITE_LABEL[x.result])}</a>`).join('')}` : ''}</section>
   <section class="station ${inf.reviewed ? 'ok' : 'warn'}" id="st-review"><h2>Human review</h2><div class="q">You decide. The system records it.</div>${f ? `<div class="panel"><div class="pb">${reviewForm(C, f)}</div></div>` : '<div class="note">Run analysis to create a review item for this claim.</div>'}</section>
   <section class="station" id="st-audit"><h2>Audit history</h2><div class="q">What has happened to this claim?</div>${auditEv.length ? `<ul class="tl">${auditEv.slice(-10).reverse().map(e => `<li class="${e.actorType === 'AI' ? 'ai' : e.actorType === 'REVIEWER' ? 'rev' : ''}"><div class="t">${esc(fmtClock(e.ts))} · ${esc(e.event)}</div><div class="d">${esc(e.description)}</div></li>`).join('')}</ul>` : '<p class="muted">No events recorded yet.</p>'}</section></div>
   <aside class="sticky-side"><section class="panel"><div class="ph"><h2>System assessment</h2>${aiTag('claim', c.id)}</div><div class="pb"><div class="sigrow"><span>Support</span>${sig(c.supportStrength, 'ok')}<span class="mono faint">/ 100</span></div><div class="sigrow"><span>Conflict</span>${sig(c.conflictStrength, 'bad')}<span class="mono faint">/ 100</span></div><div class="sigrow"><span>Uncertainty</span>${sig(c.uncertainty, 'warn')}<span class="mono faint">/ 100</span></div><details style="margin-top:8px"><summary style="cursor:pointer;font-size:12.5px;color:var(--accent-text)">Why these signals</summary><div class="lbl" style="margin:10px 0 2px">Support</div><ul class="factors">${factors('support')}</ul><div class="lbl" style="margin:10px 0 2px">Conflict</div><ul class="factors">${factors('conflict')}</ul><div class="lbl" style="margin:10px 0 2px">Uncertainty</div><ul class="factors">${factors('uncertainty')}</ul></details><div style="margin-top:12px">${SIG_NOTE}</div></div></section>
   <section class="panel"><div class="ph"><h2>Provenance</h2></div><div class="pb"><dl class="kv" style="grid-template-columns:100px 1fr;font-size:12.5px"><dt>Generated by</dt><dd class="mono">${esc(c.agent)}</dd><dt>Provider</dt><dd class="mono">${esc(c.provider || 'local-rules')}${c.model ? ' · ' + esc(c.model) : ''}</dd><dt>Generated</dt><dd class="mono">${esc(fmtDT(c.generatedAt))}</dd><dt>Extraction</dt><dd>${Math.round(c.confidence * 100)}% — extraction certainty only, not truth or legal validity</dd>${c.uncertaintyFlags.length ? `<dt>Language</dt><dd>Hedged wording (${esc(c.uncertaintyFlags.join(', ').toLowerCase().replace(/_/g, ' '))}). Recorded for context; says nothing about honesty.</dd>` : ''}</dl></div></section></aside></div>`;
  return { title: c.id, workspace: 'Claim detail', crumbs: crumbsFor(C, ['Claims', caseHref(C, 'claims')], [c.id]), mount() { if (f) openFinding(C, f); },
    html: `<div class="page wide"><div class="row wrap between" style="margin-bottom:10px"><div class="row" style="gap:6px">${prev ? linkBtn(prev.id, caseHref(C, 'claims/' + prev.id), { cls: 'sm ghost', icon: 'left' }) : ''}${next ? `<a class="btn sm ghost" href="${caseHref(C, 'claims/' + next.id)}">${next.id}${icon('right', 14)}</a>` : ''}</div><div class="row wrap">${btn('Copy ID', `data-act="copy" data-text="${c.id}"`, { cls: 'sm', icon: 'copy' })}${linkBtn('Open in graph', caseHref(C, 'graph?claim=' + c.id), { cls: 'sm', icon: 'network' })}${linkBtn('Open source', X.href(c), { cls: 'sm primary', icon: 'ext' })}</div></div>
    <header style="margin-bottom:18px"><div class="row wrap" style="gap:8px;margin-bottom:8px"><span class="tag" style="font-size:13px">CLAIM ${c.id}</span>${badge(inf.status)}${inf.inConflict ? badge('CONFLICT') : ''}<span class="tag">${esc(typeLabel(c.type))}</span></div><h1 class="claimtxt">${esc(c.text)}</h1></header>${chain}${detail}</div>` };
}
ACT.compare = el => openCompare(el.dataset.id);
function openCompare(kid) {
  const C = currentCaseSafe(); if (!C) return; const X = derive(C); const k = C.conflicts.find(x => x.id === kid); if (!k) return; const fk = C.findings.find(x => x.conflictId === k.id);
  const side = (label, ids) => { const cs = ids.map(i => X.claim(i)).filter(Boolean); const c = cs[0]; if (!c) return '<div class="side">—</div>'; const d = X.doc(c.sourceDocId), p = X.para(c);
    return `<div class="side"><div class="lbl">${label}</div><div class="serif" style="font-size:17px;font-weight:600;margin:4px 0">${esc(docName(d))}</div><div class="faint" style="font-size:12.5px;margin-bottom:10px">${esc(d ? d.category : '')} · ${esc(X.src(c).split(' · ').slice(1).join(' · '))}</div><div class="passage" style="font-size:15px">${p ? `${esc(p.text.slice(0, c.start))}<mark>${esc(p.text.slice(c.start, c.end))}</mark>${esc(p.text.slice(c.end))}` : esc(c.text)}</div><dl class="kv" style="grid-template-columns:80px 1fr;margin-top:12px;font-size:12.5px"><dt>Time</dt><dd class="mono">${esc(c.eventTime ? c.eventTime.text : '—')}</dd><dt>Location</dt><dd>${esc(c.locations.map(l => l.label).join(', ') || '—')}</dd><dt>Speaker</dt><dd>${esc(c.speaker || '—')}</dd></dl>${cs.length > 1 ? `<div class="faint" style="font-size:12px;margin-top:8px">${cs.length - 1} more claim(s) on this side: ${cs.slice(1).map(x => `<a href="${caseHref(C, 'claims/' + x.id)}" class="mono">${x.id}</a>`).join(', ')}</div>` : ''}<div class="row wrap" style="margin-top:12px;gap:6px">${linkBtn('View claim ' + c.id, caseHref(C, 'claims/' + c.id), { cls: 'sm' })}${linkBtn('Open source', X.href(c), { cls: 'sm', icon: 'ext' })}</div></div>`; };
  modal({ title: `Compare sources — ${k.id}`, wide: true, body: `<div class="cmp">${side('Source A', k.sideA.includes(k.claimA) ? [k.claimA, ...k.sideA.filter(x => x !== k.claimA)] : k.sideA)}<div class="mid">${icon('swap', 24)}</div>${side('Source B', k.sideB.includes(k.claimB) ? [k.claimB, ...k.sideB.filter(x => x !== k.claimB)] : k.sideB)}</div><div class="cmpbanner">Potential inconsistency — requires human verification</div><p class="muted" style="margin-top:12px;font-size:13px">${esc(k.whyFlagged)} The system does not decide which source is accurate.</p>`, foot: `${fk ? linkBtn('Add review', caseHref(C, 'review/' + fk.id), { cls: 'primary' }) : ''}${btn('Close', 'data-act="close"')}` });
}

/* ---------- evidence register ---------- */
const EV_GROUPS = { All: null, Documents: ['DOCUMENT', 'OTHER'], CCTV: ['CCTV'], 'Phone metadata': ['PHONE_METADATA'], Medical: ['MEDICAL_RECORD'], Forensic: ['FORENSIC_REPORT'], Witness: ['WITNESS_STATEMENT', 'HEARING_STATEMENT'], Digital: ['DIGITAL_RECORD', 'PHOTOGRAPH', 'OBJECT_EXHIBIT'] };
function EvidenceView(C) {
  const head = `<div class="pagehead"><div><p class="lbl" style="margin-bottom:6px">Evidence register</p><h1>${plural(C.evidence.length, 'evidence item')}</h1><p class="sub">Every item points to a source location. Nothing is invented.</p></div><div class="row">${linkBtn('Evidence graph', caseHref(C, 'graph'), { icon: 'network' })}</div></div>`;
  if (!C.evidence.length) return { title: 'Evidence', workspace: 'Evidence register', crumbs: crumbsFor(C, ['Evidence']), html: `<div class="page">${head}${empty({ icon: 'layers', title: 'No evidence identified', text: 'Evidence items appear after the case material has been analysed.', action: `<div style="margin-top:10px">${btn('Run analysis', `data-act="run-analysis" data-case="${C.id}"`, { cls: 'primary', icon: 'play' })}</div>` })}</div>` };
  return { title: 'Evidence', workspace: 'Evidence register', crumbs: crumbsFor(C, ['Evidence']), mount: paintEvidence, html: `<div class="page wide">${head}<div class="row wrap between" style="margin-bottom:14px"><div class="chips" id="evchips"></div><div class="searchin" style="width:280px;max-width:100%">${icon('search', 15)}<input type="text" data-in="evq" placeholder="Search evidence…" aria-label="Search evidence" value="${esc(UI.ev.q)}"></div></div><div id="evlist"></div></div>` };
}
function paintEvidence() {
  const C = currentCaseSafe(); if (!C || !$('#evlist')) return; const X = derive(C); const q = UI.ev.q.trim().toLowerCase();
  $('#evchips').innerHTML = Object.keys(EV_GROUPS).map(g => `<button class="chip" aria-pressed="${UI.ev.f === g}" data-act="ev-filter" data-k="${g}">${g}<span class="n">${C.evidence.filter(e => !EV_GROUPS[g] || EV_GROUPS[g].includes(e.type)).length}</span></button>`).join('');
  const rows = C.evidence.filter(e => !EV_GROUPS[UI.ev.f] || EV_GROUPS[UI.ev.f].includes(e.type)).filter(e => !q || (e.description + e.id + (EVIDENCE_LABEL[e.type] || '')).toLowerCase().includes(q));
  $('#evlist').innerHTML = rows.length ? `<div class="tblwrap"><table><thead><tr><th>Evidence</th><th>Type</th><th>Description</th><th>Source</th><th>Linked claims</th><th>Review</th></tr></thead><tbody>${rows.map(e => { const rl = C.relationships.filter(r => r.evidenceId === e.id); const d = X.doc(e.sourceDocId); const st = !rl.length ? 'UNRESOLVED' : rl.every(r => X.info(X.claim(r.claimId)).reviewed) ? 'REVIEWED' : 'NEEDS_REVIEW'; return `<tr data-act="ev-open" data-id="${e.id}" style="cursor:pointer"><td class="idcell"><button class="tag" data-act="ev-open" data-id="${e.id}">${e.id}</button></td><td>${esc(EVIDENCE_LABEL[e.type] || e.type)}</td><td class="qtext">${esc(trunc(e.description, 120))}</td><td style="font-size:12.5px">${d ? `<a href="${docHref(C, d)}${d.kind === 'transcript' ? '' : '?page=' + e.page}">${esc(trunc(docName(d), 30))}</a>` : '—'}<div class="faint mono" style="font-size:11.5px">p.${e.page}${e.para ? ' · ¶' + e.para : ''}</div></td><td>${rl.slice(0, 4).map(r => `<a class="tag" href="${caseHref(C, 'claims/' + r.claimId)}" title="${esc(r.relationship)}">${r.claimId}</a>`).join(' ') || '<span class="faint">None</span>'}${rl.length > 4 ? ` <span class="faint">+${rl.length - 4}</span>` : ''}</td><td>${badge(st)}</td></tr>`; }).join('')}</tbody></table></div>` : empty({ icon: 'search', title: 'No evidence matches', text: 'Try another category or search term.' });
}
ACT['ev-filter'] = el => { UI.ev.f = el.dataset.k; paintEvidence(); };
INPUT.evq = t => { UI.ev.q = t.value; paintEvidence(); };
ACT['ev-open'] = el => {
  const C = currentCaseSafe(); if (!C) return; const X = derive(C); const e = X.ev.get(el.dataset.id); if (!e) return; const d = X.doc(e.sourceDocId); const rl = C.relationships.filter(r => r.evidenceId === e.id);
  drawer({ title: `Evidence ${e.id}`, body: `<div class="row between" style="margin-bottom:10px"><span class="tag">${esc(EVIDENCE_LABEL[e.type] || e.type)}</span>${aiTag('evidence', e.id)}</div><p class="serif" style="font-size:16px;line-height:1.5">${esc(e.description)}</p>
  <div class="chain vertical" style="margin:16px 0">${chainCell('file', 'Source', esc(d ? docName(d) : '—'), `Page ${e.page}${e.para ? ' · Paragraph ' + e.para : ''}`, { href: d ? docHref(C, d) + (d.kind === 'transcript' ? '' : '?page=' + e.page) : '#' })}${chainCell('layers', 'Evidence', e.id, esc(EVIDENCE_LABEL[e.type] || e.type))}${chainCell('quote', 'Linked claims', rl.length ? plural(rl.length, 'claim') : 'None', rl.slice(0, 3).map(r => r.claimId).join(', ') || 'No claim is linked yet')}</div>
  ${rl.length ? `<div class="lbl" style="margin-bottom:8px">Relationships</div>${rl.map(r => { const c = X.claim(r.claimId); return `<a class="cardbtn" href="${caseHref(C, 'claims/' + r.claimId)}"><div class="row between"><span class="idcell">${r.claimId}</span>${relBadge(r.relationship)}</div><div class="serif" style="margin-top:4px;font-size:14px">${esc(trunc(c ? c.text : '', 110))}</div><div class="muted" style="font-size:12px;margin-top:4px">${esc(r.reason)}</div></a>`; }).join('')}` : '<p class="muted">No claim is linked to this evidence item.</p>'}
  <div class="note" style="margin-top:14px">${icon('info', 14)}<span>Generated by <span class="mono">${esc(e.agent)}</span> at ${esc(fmtDT(e.generatedAt))}. Not independently verified.</span></div>` });
};

/* ---------- conflicts ---------- */
function timeGap(a, b) { if (!a || !b) return null; if (a.a <= b.b && b.a <= a.b) return 'The stated time intervals overlap.'; const g = Math.min(Math.abs(a.a - b.b), Math.abs(b.a - a.b)); return `${Math.round(g)} minutes between the stated times.`; }
function ConflictsView(C) {
  const X = derive(C); const head = `<div class="pagehead"><div><p class="lbl" style="margin-bottom:6px">Potential conflicts</p><h1>${C.conflicts.length ? plural(C.conflicts.length, 'potential conflict') : 'No potential conflicts'}</h1><p class="sub">Sources that appear to describe the same time, place or event differently. The system surfaces them; it never decides which is accurate.</p></div></div>`;
  if (!C.conflicts.length) return { title: 'Conflicts', workspace: 'Potential conflicts', crumbs: crumbsFor(C, ['Conflicts']), html: `<div class="page narrow">${head}${empty({ icon: 'check', title: C.claims.length ? 'No potential conflicts identified' : 'No analysis yet', text: C.claims.length ? 'No potential evidence conflicts were identified in the current analysis.' : 'Run the analysis to compare the claims across sources.', action: `<div style="margin-top:10px">${btn(C.claims.length ? 'Re-run analysis' : 'Run analysis', `data-act="run-analysis" data-case="${C.id}"`, { cls: 'primary', icon: 'play' })}</div>` })}</div>` };
  return { title: 'Conflicts', workspace: 'Potential conflicts', crumbs: crumbsFor(C, ['Conflicts']), html: `<div class="page narrow">${head}<div class="col">${C.conflicts.map(k => {
    const a = X.claim(k.claimA), b = X.claim(k.claimB); const da = a && X.doc(a.sourceDocId), db = b && X.doc(b.sourceDocId); const fk = C.findings.find(x => x.conflictId === k.id); const gap = timeGap(a && a.eventTime, b && b.eventTime);
    return `<article class="panel"><div class="ph"><div class="row" style="gap:8px"><span class="tag">${k.id}</span><b>${esc(typeLabel(k.type))} inconsistency</b></div><div class="row">${fk ? badge(findingStatus(C, fk)) : ''}${aiTag('conflict', k.id)}</div></div><div class="pb col" style="gap:14px">
     <div class="row wrap" style="gap:12px;align-items:stretch"><div class="grow" style="min-width:220px;padding:10px 12px;border:1px solid var(--line);border-radius:var(--r);background:var(--sunken)"><div class="lbl">Source A</div><div class="serif" style="font-weight:600;font-size:15px">${esc(docName(da))}</div><div class="faint" style="font-size:12px">${esc(a ? X.src(a).split(' · ').slice(1).join(' · ') : '')}</div><div class="serif" style="font-size:14.5px;margin-top:6px">${esc(a ? trunc(a.text, 130) : '')}</div></div><div style="display:grid;place-items:center;color:var(--warn-t)">${icon('swap', 22)}</div><div class="grow" style="min-width:220px;padding:10px 12px;border:1px solid var(--line);border-radius:var(--r);background:var(--sunken)"><div class="lbl">Source B</div><div class="serif" style="font-weight:600;font-size:15px">${esc(docName(db))}</div><div class="faint" style="font-size:12px">${esc(b ? X.src(b).split(' · ').slice(1).join(' · ') : '')}</div><div class="serif" style="font-size:14.5px;margin-top:6px">${esc(b ? trunc(b.text, 130) : '')}</div></div></div>
     <div><div class="lbl" style="margin-bottom:4px">Why flagged</div><p>${esc(k.whyFlagged)}${gap ? ' ' + esc(gap) : ''}</p>${k.claims.length > 2 ? `<p class="faint" style="font-size:12.5px;margin-top:4px">${k.claims.length - 2} further claim(s) describe the same locations: ${k.claims.filter(x => x !== k.claimA && x !== k.claimB).map(x => `<a class="mono" href="${caseHref(C, 'claims/' + x)}">${x}</a>`).join(', ')}</p>` : ''}</div>
     <div class="row wrap" style="gap:8px">${btn('Compare sources', `data-act="compare" data-id="${k.id}"`, { cls: 'primary', icon: 'compare' })}${da ? linkBtn('Open document', X.href(a), { icon: 'ext' }) : ''}${linkBtn('View timeline', caseHref(C, 'timeline'), { icon: 'clock' })}${fk ? linkBtn('Review finding', caseHref(C, 'review/' + fk.id), { icon: 'eye' }) : ''}</div><div>${HUMAN_NOTE}</div></div></article>`; }).join('')}</div></div>` };
}

/* ---------- authority library + research ---------- */
function authForm() {
  const f = (id, label, ctl, hint) => `<div class="field" data-f="${id}"><label for="a-${id}">${label}</label>${ctl}${hint ? `<span class="hint">${hint}</span>` : ''}<span class="err hide" id="e-${id}"></span></div>`;
  return `<form data-form="authadd" novalidate class="col" style="gap:12px"><div class="fgrid">${f('title', 'Title *', '<input id="a-title" name="title" type="text" maxlength="200">')}${f('citation', 'Citation', '<input id="a-citation" name="citation" type="text" maxlength="80" placeholder="e.g. reporter reference or short name">', 'Used to match citations in your documents.')}${f('court', 'Court / body', '<input id="a-court" name="court" type="text" maxlength="120">')}${f('year', 'Year', '<input id="a-year" name="year" type="number" min="1000" max="2100">')}${f('kind', 'Type', `<select id="a-kind" name="kind">${AUTH_KINDS.map(k => `<option>${k}</option>`).join('')}</select>`)}${f('sourceNote', 'Where it came from', '<input id="a-sourceNote" name="sourceNote" type="text" maxlength="300" placeholder="Reporter, website or file it was copied from">')}</div>
  ${f('keywords', 'Key terms (optional)', '<input id="a-keywords" name="keywords" type="text" maxlength="300" placeholder="Words that describe what it is about">')}
  <div class="field" data-f="text"><div class="row between"><label for="a-text">Authority text *</label><span class="row" style="gap:6px">${btn('Load from file', 'data-act="pick-files" data-target="authfile"', { cls: 'sm', icon: 'upload' })}<input id="authfile" type="file" accept=".pdf,.docx,.txt,.md" class="hide" data-change="authfile"></span></div><textarea id="a-text" name="text" style="min-height:160px" placeholder="Paste the judgment, statute or passage. Number paragraphs like “27. …” so citations such as “paragraph 27” can be matched."></textarea><span class="err hide" id="e-text"></span></div>
  <div class="note">${icon('info', 14)}<span>Only add text from a source you trust. The system does not check whether an authority is genuine, current or correctly transcribed.</span></div><div class="row" style="justify-content:flex-end"><button class="btn primary" type="submit">Add to library</button></div></form>`;
}
FORM.authadd = async f => { const d = {}; new FormData(f).forEach((v, k) => d[k] = v); try { await Data.addAuthority(d); toast('Authority added to your library. Re-run the analysis to use it.'); render(); } catch (e) { if (e.errors) showFieldErrors(f, e.errors); else toast('Unable to add the authority.', 'bad'); } };
INPUT.authfile = async t => { const f = t.files[0]; if (!f) return; const r = await parseFile(f); if (!r.ok) { toast(r.error, 'warn'); return; } $('#a-text').value = r.text.replace(/\f/g, '\n\n'); if (!$('#a-title').value) $('#a-title').value = f.name.replace(/\.[a-z0-9]+$/i, ''); toast('Text loaded. Review it before adding.'); t.value = ''; };
ACT['auth-remove'] = el => { const a = AUTH_BY_ID[el.dataset.id]; confirmDialog({ title: 'Remove this authority?', text: `“${esc(a ? a.title : el.dataset.id)}” is deleted from your library. Existing links keep working until you re-run the analysis.`, label: 'Remove', danger: true, onConfirm: async () => { try { await Data.removeAuthority(el.dataset.id); toast('Authority removed.'); render(); } catch (e) { toast(e.message, 'bad'); } } }); };
ACT['auth-add-toggle'] = () => { const w = $('#authaddwrap'); w && w.classList.toggle('hide'); };
function AuthoritiesView(C, q) {
  const u = UI.user; useLibrary(u.id); const lib = AuthSvc.list(u.id); UI.au.q = q && q.q != null ? q.q : UI.au.q;
  const links = C ? uniq(C.authorityLinks.map(l => l.authorityId)) : [];
  const crumbs = C ? crumbsFor(C, ['Authorities']) : [['Authorities']];
  return { title: 'Authorities', workspace: 'Authority research', crumbs, case: C, mount() { paintAuth(); },
    html: `<div class="page"><div class="pagehead"><div><p class="lbl" style="margin-bottom:6px">Authority research</p><h1>Search your authority library</h1><p class="sub">Retrieval ranks passages by lexical similarity. A high rank means a passage appears related, not that it is correct or binding.</p></div>${btn(lib.length ? 'Add authority' : 'Add your first authority', 'data-act="auth-add-toggle"', { cls: 'primary', icon: 'plus' })}</div>
    <div class="col"><section class="panel ${lib.length ? 'hide' : ''}" id="authaddwrap"><div class="ph"><h2>Add an authority to your library</h2></div><div class="pb">${authForm()}</div></section>
    <div class="searchin">${icon('search', 16)}<input type="text" id="authq" data-in="authq" placeholder="Search legislation, judgments, sections, legal authorities…" aria-label="Search authorities" value="${esc(UI.au.q)}" style="height:44px;font-size:15px"></div><div id="authres"></div>
    ${C && links.length ? `<section class="panel"><div class="ph"><h2>Retrieved for this case</h2><span class="faint" style="font-size:12px">${plural(C.authorityLinks.length, 'claim link')}</span></div><div class="list">${links.map(id => { const a = AUTH_BY_ID[id]; const cl = C.authorityLinks.filter(l => l.authorityId === id); return a ? `<div class="li"><span class="ic-wrap info">${icon('book', 15)}</span><span class="grow"><b class="serif">${esc(a.title)}</b> <span class="tag">${esc(a.citation)}</span><br>${cl.slice(0, 8).map(l => `<a class="tag" href="${caseHref(C, 'claims/' + l.claimId)}" style="margin:3px 4px 0 0">${l.claimId}</a>`).join('')}</span></div>` : ''; }).join('')}</div></section>` : ''}
    <section class="panel"><div class="ph"><h2>Your library</h2><span class="mono faint">${lib.length}</span></div>${lib.length ? `<div class="list">${lib.map(a => `<div class="li"><span class="ic-wrap">${icon('book', 15)}</span><span class="grow"><b class="serif" style="font-size:15px">${esc(a.title)}</b> <span class="tag">${esc(a.citation)}</span><div class="faint" style="font-size:12.5px">${esc([a.kind, a.court, a.year].filter(Boolean).join(' · '))} · ${plural(a.paras.length, 'passage')}${a.sourceNote ? ' · ' + esc(a.sourceNote) : ''}</div></span><button class="iconbtn" data-act="auth-remove" data-id="${a.id}" aria-label="Remove ${esc(a.title)}">${icon('trash', 15)}</button></div>`).join('')}</div>` : `<div class="pb muted">The library is empty. The app ships with no authorities, so nothing is invented. Add the judgments and statutes you rely on.</div>`}</section></div></div>` };
}
function paintAuth() {
  const el = $('#authres'); if (!el) return; const q = UI.au.q.trim(); if (q.length < 3) { el.innerHTML = ''; return; }
  useLibrary(UI.user.id); const res = searchAuthorities(q, 8); const C = currentCaseSafe();
  el.innerHTML = res.length ? res.map(r => `<article class="panel" style="margin-bottom:12px"><div class="pb"><div class="row wrap between"><div><b class="serif" style="font-size:17px">${esc(r.title)}</b><div class="faint" style="font-size:12.5px;margin-top:2px"><span class="mono">${esc(r.citation)}</span>${copyBtn(r.citation, 'Copy citation')} · ${esc([r.kind, r.court, r.year].filter(Boolean).join(' · '))}</div></div>${HUMAN_NOTE}</div><div class="lbl" style="margin:12px 0 4px">Relevant passage ${r.passageIndex}</div><div class="passage" style="font-size:15px">${markTerms(r.passage, r.matchedTerms)}</div><div class="row wrap between" style="margin-top:10px"><span class="faint" style="font-size:12.5px">Relevance assessment: retrieval signal <span class="mono">${r.relevanceScore}</span> — a ranking signal, not legal correctness. Source: ${esc(r.sourceNote || 'your library')}.</span>${C ? `<span>${C.authorityLinks.filter(l => l.authorityId === r.authorityId).slice(0, 4).map(l => `<a class="tag" href="${caseHref(C, 'claims/' + l.claimId)}">${l.claimId}</a>`).join(' ')}</span>` : ''}</div></div></article>`).join('') : empty({ icon: 'search', title: 'No passage matched', text: 'Try different words, or add the relevant authority to your library.' });
}
const markTerms = (t, terms) => { let out = esc(t); (terms || []).forEach(w => { if (w.length > 2) out = out.replace(new RegExp('(' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\w*)', 'gi'), '<mark class="q" style="background:var(--gold-soft);color:inherit">$1</mark>'); }); return out; };
INPUT.authq = t => { UI.au.q = t.value; paintAuth(); };

/* ---------- citation audit: forensic comparison ---------- */
function CitationsView(C, q) {
  const X = derive(C); const head = `<div class="pagehead"><div><p class="lbl" style="margin-bottom:6px">Citation audit</p><h1>${plural(C.citations.length, 'citation')} checked</h1><p class="sub">Each citation is compared with the text of the authority in your library. A result is a lexical comparison, never a finding that the law is verified.</p></div></div>`;
  if (!C.citations.length) return { title: 'Citation audit', workspace: 'Citation audit', crumbs: crumbsFor(C, ['Citation audit']), html: `<div class="page narrow">${head}${empty({ icon: 'shield', title: 'No citations found', text: C.claims.length ? 'No citations or legal propositions were found in the case material. Citations matching your authority library, and “[1] Title, paragraph N” references, are detected automatically.' : 'Citations appear here after the case material has been analysed.', action: `<div style="margin-top:10px">${btn(C.claims.length ? 'Re-run analysis' : 'Run analysis', `data-act="run-analysis" data-case="${C.id}"`, { cls: 'primary', icon: 'play' })}</div>` })}</div>` };
  const sel = C.citations.find(x => x.id === q.cit) || C.citations.find(x => x.result === 'WEAK_RELEVANCE') || C.citations.find(x => x.result !== 'POTENTIALLY_RELEVANT') || C.citations[0];
  const toks = s => new Set(tokens(s)); const pt = toks(sel.proposition), mt = sel.matchedPassage ? toks(sel.matchedPassage.text) : new Set();
  const mk = (text, other) => text.split(/(\s+)/).map(w => { if (!w.trim()) return w; const t = tokens(w)[0]; if (!t) return esc(w); return other.has(t) ? `<mark class="same">${esc(w)}</mark>` : (other.size ? `<mark class="diff">${esc(w)}</mark>` : esc(w)); }).join('');
  const missing = Array.from(pt).filter(t => !mt.has(t)).length; const a = sel.authorityId ? AUTH_BY_ID[sel.authorityId] : null; const f = C.findings.find(x => x.citationId === sel.id);
  const detail = `<section class="panel" style="margin-bottom:18px"><div class="ph"><div class="row" style="gap:8px"><span class="tag">${sel.id}</span><b>Citation comparison</b></div><div class="row">${badge(sel.result === 'POTENTIALLY_RELEVANT' ? 'ACCEPTED' : 'NEEDS_REVIEW', CITE_LABEL[sel.result])}${aiTag('citation', sel.id)}</div></div><div class="pb col" style="gap:14px">
    <div class="chain" style="margin:0">${chainCell('quote', 'Claim / proposition', sel.claimId || '—', `p.${sel.page} · ¶${sel.para}`, { href: sel.claimId ? caseHref(C, 'claims/' + sel.claimId) : caseHref(C, 'documents/' + sel.docId + '?page=' + sel.page) })}${chainCell('shield', 'Citation', esc(trunc(sel.citationText, 28)), sel.kind === 'MISSING' ? 'no citation attached' : 'as written')}${chainCell('book', 'Authority', a ? esc(trunc(a.citation, 24)) : 'Not resolved', a ? esc(trunc(a.title, 30)) : 'not in your library', { cls: a ? '' : 'warn' })}${chainCell('scale', 'Match', sel.result === 'POTENTIALLY_RELEVANT' ? 'Related' : sel.result === 'WEAK_RELEVANCE' ? 'Partial' : 'None', `signal ${sel.relevanceSignal}`)}${chainCell('eye', 'Review', f ? esc(REVIEW_BADGE[findingStatus(C, f) === 'PENDING' ? 'PENDING' : findingStatus(C, f)][2]) : 'Included', f ? f.id : 'no issue raised', { cls: f && findingStatus(C, f) === 'PENDING' ? 'warn' : 'ok' })}</div>
    <div class="fcmp"><div><div class="hd">Cited proposition · ${esc(docName(X.doc(sel.docId)))}, p.${sel.page}</div>${mk(sel.proposition, mt) || '—'}</div><div><div class="hd">${a ? 'Retrieved source text · ' + esc(a.citation) + (sel.matchedPassage ? ', passage ' + sel.matchedPassage.idx : '') : 'Retrieved source text'}</div>${sel.matchedPassage ? mk(sel.matchedPassage.text, pt) : '<span class="muted" style="font-family:var(--font)">No source text could be retrieved for this citation.</span>'}</div></div>
    ${sel.matchedPassage ? `<div class="faint" style="font-size:12.5px"><span class="badge ok" style="margin-right:6px">shared terms</span><span class="badge warn">not in the passage: ${missing}</span> Difference is counted in terms, not meaning.</div>` : ''}
    <div class="note">${icon('info', 14)}<span>${esc(sel.note)}</span></div>${f ? `<div class="panel"><div class="pb">${reviewForm(C, f)}</div></div>` : ''}</div></section>`;
  return { title: 'Citation audit', workspace: 'Citation audit', crumbs: crumbsFor(C, ['Citation audit']), mount() { if (f) openFinding(C, f); }, html: `<div class="page wide">${head}${detail}<div class="tblwrap"><table><thead><tr><th>Citation</th><th>Claim</th><th>Cited text</th><th>Authority</th><th>Result</th><th>Signal</th></tr></thead><tbody>${C.citations.map(x => `<tr data-href="${caseHref(C, 'citations?cit=' + x.id)}" ${x.id === sel.id ? 'style="background:var(--accent-soft)"' : ''}><td class="idcell">${x.id}</td><td class="idcell">${x.claimId ? `<a href="${caseHref(C, 'claims/' + x.claimId)}">${x.claimId}</a>` : '—'}</td><td class="mono" style="font-size:12px;max-width:260px">${esc(trunc(x.citationText, 60))}</td><td>${x.authorityId && AUTH_BY_ID[x.authorityId] ? esc(trunc(AUTH_BY_ID[x.authorityId].citation, 26)) : '—'}</td><td>${badge(x.result === 'POTENTIALLY_RELEVANT' ? 'ACCEPTED' : 'NEEDS_REVIEW', CITE_LABEL[x.result])}</td><td class="mono">${x.relevanceSignal}</td></tr>`).join('')}</tbody></table></div></div>` };
}

/* ---------- timeline ---------- */
function TimelineView(C) {
  const head = `<div class="pagehead"><div><p class="lbl" style="margin-bottom:6px">Case timeline</p><h1>Events across sources</h1><p class="sub">Times are compared within a single day; dates are not compared. Overlapping or differing accounts are shown as potential inconsistencies for review.</p></div></div>`;
  const ev = C.claims.filter(c => c.eventTime);
  if (!ev.length) return { title: 'Timeline', workspace: 'Case timeline', crumbs: crumbsFor(C, ['Timeline']), html: `<div class="page narrow">${head}${empty({ icon: 'clock', title: 'No timed events', text: C.claims.length ? 'None of the extracted claims carries a time reference.' : 'The timeline is built from times mentioned in claims. Run the analysis first.', action: `<div style="margin-top:10px">${C.claims.length ? '' : btn('Run analysis', `data-act="run-analysis" data-case="${C.id}"`, { cls: 'primary', icon: 'play' })}</div>` })}</div>` };
  const X = derive(C); const docsIn = uniq(ev.map(c => c.sourceDocId)); const spk = uniq(ev.map(c => c.speaker).filter(Boolean));
  return { title: 'Timeline', workspace: 'Case timeline', crumbs: crumbsFor(C, ['Timeline']), mount: paintTimeline, html: `<div class="page wide">${head}<div class="row wrap" style="margin-bottom:14px;gap:12px"><div class="field" style="min-width:200px"><label for="tl-doc">Source</label><select id="tl-doc" data-change="tldoc"><option value="">All sources</option>${docsIn.map(id => `<option value="${id}" ${UI.tl.doc === id ? 'selected' : ''}>${esc(docName(X.doc(id)))}</option>`).join('')}</select></div><div class="field" style="min-width:160px"><label for="tl-spk">Speaker</label><select id="tl-spk" data-change="tlspk"><option value="">All speakers</option>${spk.map(s => `<option ${UI.tl.spk === s ? 'selected' : ''}>${esc(s)}</option>`).join('')}</select></div><label class="row" style="align-self:end;height:36px;cursor:pointer"><input type="checkbox" data-change="tlov" ${UI.tl.overlay ? 'checked' : ''}> Show potential-conflict overlay</label></div><div id="tlchart"></div><div id="tllist" style="margin-top:18px"></div><p class="faint" style="font-size:12.5px;margin-top:10px">${plural(C.claims.length - ev.length, 'claim')} without a time reference are not shown.</p></div>` };
}
INPUT.tldoc = t => { UI.tl.doc = t.value; paintTimeline(); }; INPUT.tlspk = t => { UI.tl.spk = t.value; paintTimeline(); }; INPUT.tlov = t => { UI.tl.overlay = t.checked; paintTimeline(); };
function paintTimeline() {
  const C = currentCaseSafe(); if (!C || !$('#tlchart')) return; const X = derive(C);
  const ev = C.claims.filter(c => c.eventTime && (!UI.tl.doc || c.sourceDocId === UI.tl.doc) && (!UI.tl.spk || c.speaker === UI.tl.spk)).sort((a, b) => a.eventTime.a - b.eventTime.a);
  if (!ev.length) { $('#tlchart').innerHTML = empty({ icon: 'filter', title: 'No events match', text: 'Change the source or speaker filter.' }); $('#tllist').innerHTML = ''; return; }
  const lo = Math.floor((Math.min(...ev.map(c => c.eventTime.a)) - 20) / 30) * 30, hi = Math.ceil((Math.max(...ev.map(c => c.eventTime.b)) + 20) / 30) * 30, span = Math.max(30, hi - lo); const W = 1000, PL = 150, PR = 24, x = m => PL + (m - lo) / span * (W - PL - PR);
  const lanes = uniq(ev.map(c => c.sourceDocId)); const LH = 44, H = 34 + lanes.length * LH; const ly = id => 34 + lanes.indexOf(id) * LH + LH / 2; let ticks = ''; const step = span > 300 ? 60 : 30; for (let m = Math.ceil(lo / step) * step; m <= hi; m += step) ticks += `<line x1="${x(m)}" x2="${x(m)}" y1="24" y2="${H}" stroke="var(--line)" stroke-dasharray="2 4"/><text x="${x(m)}" y="16" text-anchor="middle" font-size="10.5" font-family="var(--mono)" fill="var(--text-3)">${minToClock(m)}</text>`;
  const pos = {}; ev.forEach(c => { pos[c.id] = { x: (x(c.eventTime.a) + x(c.eventTime.b)) / 2, y: ly(c.sourceDocId) }; });
  const ov = UI.tl.overlay ? C.conflicts.flatMap(k => { const a = pos[k.claimA], b = pos[k.claimB]; return a && b ? [`<path d="M${a.x} ${a.y} C ${a.x} ${(a.y + b.y) / 2}, ${b.x} ${(a.y + b.y) / 2}, ${b.x} ${b.y}" fill="none" stroke="var(--warn)" stroke-width="1.6" stroke-dasharray="5 4"><title>${k.id}: potential ${typeLabel(k.type).toLowerCase()} inconsistency</title></path>`] : []; }).join('') : '';
  $('#tlchart').innerHTML = `<div class="htl"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Timeline of claims by source">${ticks}${lanes.map(id => `<text x="0" y="${ly(id) + 4}" font-size="12" font-family="var(--serif)" font-weight="600" fill="var(--text)">${esc(trunc(docName(X.doc(id)), 20))}</text><line x1="${PL}" x2="${W - PR}" y1="${ly(id)}" y2="${ly(id)}" stroke="var(--line-2)"/>`).join('')}${ov}${ev.map(c => { const inC = X.info(c).inConflict; const a = x(c.eventTime.a), b = x(c.eventTime.b), y = ly(c.sourceDocId); const col = inC ? 'var(--warn)' : 'var(--accent)'; return `<g role="button" tabindex="0" data-act="nav" data-href="${caseHref(C, 'claims/' + c.id)}" style="cursor:pointer"><title>${c.id} · ${esc(c.eventTime.text)} · ${esc(trunc(c.text, 80))}</title>${b - a > 4 ? `<rect x="${a}" y="${y - 6}" width="${b - a}" height="12" rx="3" fill="${col}" opacity=".35"/>` : ''}<circle cx="${(a + b) / 2}" cy="${y}" r="6" fill="${col}" stroke="var(--surface)" stroke-width="2"/></g>`; }).join('')}</svg></div><div class="legend" style="margin-top:8px"><span><i style="background:var(--accent)"></i>Claim time</span><span><i style="background:var(--warn)"></i>In a potential conflict</span><span><svg width="24" height="6"><line x1="0" y1="3" x2="24" y2="3" stroke="var(--warn)" stroke-width="2" stroke-dasharray="5 4"/></svg> Potential inconsistency</span></div>`;
  $('#tllist').innerHTML = `<div class="tblwrap"><table><thead><tr><th>Time</th><th>Source</th><th>Event</th><th>Claim</th><th>Evidence</th><th>Uncertainty</th><th>Review</th></tr></thead><tbody>${ev.map(c => { const i = X.info(c); return `<tr data-href="${caseHref(C, 'claims/' + c.id)}"><td class="mono" style="white-space:nowrap">${esc(c.eventTime.text)}</td><td style="font-size:12.5px"><a href="${X.href(c)}">${esc(trunc(docName(X.doc(c.sourceDocId)), 26))}</a></td><td class="serif qtext" style="font-size:14px">${esc(trunc(c.text, 130))}${i.inConflict ? `<div style="margin-top:4px">${badge('CONFLICT', 'Potential inconsistency — requires human verification')}</div>` : ''}</td><td class="idcell">${c.id}</td><td class="mono" style="font-size:12px">${i.strong.slice(0, 3).map(r => r.ev.id).join(', ') || '—'}</td><td>${c.hedge ? badge('UNCERTAIN') : '<span class="faint">—</span>'}</td><td>${badge(i.status)}</td></tr>`; }).join('')}</tbody></table></div>`;
}
